#!/usr/bin/env python3
"""Forward-only r3 legacy cancellation reconciliation repair. One upload; no booking-row or provider writes."""
import base64,fcntl,hashlib,json,os,pwd,re,stat,subprocess,sys,tempfile,types,zlib
from pathlib import Path
BASE = ''
BASE_SHA = '5eaff68a7b05893f810ddbb1a063307604872e2c285c707192e9844db309bfca'
BUNDLE = ''
BUNDLE_SHA = '2a9fe0026c76675838d0711a876cf3c3f1b024d9fbd88e042870e94e73d15743'
REVISION='20260928-r4'
JOURNAL='legacy-cancellation-repair.json'
ROOT=Path('/home/sitesee/.sitesee-real-estate')
CRON=Path('/etc/cron.d/sitesee-booking-reconcile')
PUBLIC=Path('/home/sitesee/public_html/re')

def unpack(value,digest):
 data=zlib.decompress(base64.b64decode(value))
 if hashlib.sha256(data).hexdigest()!=digest:raise RuntimeError('Packaged integrity differs.')
 return data

def load():
 previous=types.ModuleType('reviewed_r3');previous.__file__=__file__;exec(compile(unpack(BASE,BASE_SHA),'reviewed-r3','exec'),previous.__dict__)
 x,m,r2,before,r3,_=previous.load();old=dict(r2,**r3);x.REVISION='20260928-r3'
 data=json.loads(unpack(BUNDLE,BUNDLE_SHA))
 return x,m,old,before,{k:v.encode() for k,v in data['files'].items()},data['report']

def cli_php(candidates):
 for path in candidates:
  if not Path(path).is_file():continue
  try:
   p=subprocess.run([str(path),'-r','echo PHP_SAPI;'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=10)
   if p.returncode==0 and p.stdout==b'cli':return str(path)
  except (OSError,subprocess.TimeoutExpired):pass
 raise RuntimeError('No verified PHP CLI executable. No application files changed.')

def cron_bytes(php):
 return ('# SiteSee TEST lifecycle: provider reads only; never sends invitations or changes payments.\n'
  '*/5 * * * * sitesee umask 077; /usr/bin/flock -n /home/sitesee/.sitesee-real-estate/lifecycle-worker.lock '
  +php+' /home/sitesee/.sitesee-real-estate/server/booking-lifecycle-reconcile.php '
  '>> /home/sitesee/.sitesee-real-estate/lifecycle-reconcile.log 2>&1\n').encode()

def plan(x,m,root,public,cron,uid,old,before,patch,php):
 # Every deployed r3 module and pinned dependency must be known; operator edits are preserved.
 for name,expected in before.items():
  current=m.private_bytes(root/name,uid,private=False)
  allowed={expected}
  if name in old:allowed.add(m.digest(old[name]))
  if name in patch:allowed.add(m.digest(patch[name]))
  m.need(m.digest(current) in allowed,'Unreviewed dependency preserved: '+name)
 for name,data in old.items():
  p=(public/Path(name).name) if name.startswith('public/') else root/name
  current=m.private_bytes(p,uid,private=False)
  m.need(current in (data,patch.get(name,data)),'Unreviewed release file preserved: '+name)
 m.need(m.private_bytes(root/x.ACTIVATION,uid)==m.encode(x.CONFIG),'TEST activation differs; preserved.')
 current=m.private_bytes(cron,0,private=False)
 m.need(current in (x.cron_bytes(m),cron_bytes(php)),'Unreviewed cron job preserved.')
 updated=dict(old,**patch)
 oldrecord={'release':x.RELEASE,'revision':x.REVISION,'files':{n:m.digest(b) for n,b in old.items()}}
 newrecord={'release':x.RELEASE,'revision':REVISION,'files':{n:m.digest(b) for n,b in updated.items()}}
 m.need(json.loads(m.private_bytes(root/x.MANIFEST,uid)) in (oldrecord,newrecord),'Lifecycle manifest differs; preserved.')
 values=dict(patch)
 # Historical manifests must still agree with known bytes. Update hashes without dropping their other entries.
 for name in ('calendar-confirmation-release.json','microsoft-scheduling-release.json','booking-workflow-release.json'):
  record=json.loads(m.private_bytes(root/name,uid));m.need(isinstance(record.get('files'),dict),'Release metadata differs.')
  for n,digest in record['files'].items():
   p=m.safe_path(root,n);actual=m.private_bytes(p,uid,private=False)
   allowed={m.digest(actual)}
   if n in old:allowed.add(m.digest(old[n]))
   if n in patch:allowed.add(m.digest(patch[n]))
   m.need(digest in allowed,'Release dependency mismatch: '+n)
  record['files'].update({n:m.digest(b) for n,b in patch.items()});values[name]=m.encode(record)
 values[x.MANIFEST]=m.encode(newrecord);values['cron/reconcile']=cron_bytes(php)
 return values

def target(root,cron,name):return cron if name=='cron/reconcile' else root/name

def deploy(m,root,cron,values,uid,gid,write=None):
 write=write or m.atomic_write
 path=root/JOURNAL
 j=json.loads(m.private_bytes(path,uid)) if path.exists() else None
 if j is not None:
  m.need(j.get('revision')==REVISION and j.get('state') in ('prepared','installed'),'Repair journal differs.')
  m.need(set(j['entries'])==set(values),'Repair file set differs.')
  m.need(re.fullmatch(r'appointment-repair-[A-Za-z0-9_-]+',j.get('backup','')) is not None,'Backup path differs.')
  for n,b in values.items():
   backup=m.safe_path(root,'deployment-backups/'+j['backup']+'/'+n)
   m.need(m.digest(m.private_bytes(backup,0))==j['entries'][n]['old'],'Backup integrity differs: '+n)
   m.need(j['entries'][n]['new']==m.digest(b),'Repair target differs.')
   p=target(root,cron,n);owner=0 if n=='cron/reconcile' else uid
   current=m.private_bytes(p,owner,private=False)
   m.need(m.digest(current) in (j['entries'][n]['old'],j['entries'][n]['new']),'Concurrent edit preserved: '+n)
 else:
  folder=Path(tempfile.mkdtemp(prefix='appointment-repair-',dir=root/'deployment-backups'));entries={}
  for n,b in values.items():
   p=target(root,cron,n);current=m.private_bytes(p,0 if n=='cron/reconcile' else uid,private=False)
   backup=folder/n;backup.parent.mkdir(parents=True,exist_ok=True,mode=0o700);m.atomic_write(backup,current,0,0)
   entries[n]={'old':m.digest(current),'new':m.digest(b)}
  j={'revision':REVISION,'state':'prepared','backup':folder.name,'entries':entries};m.atomic_write(path,m.encode(j),uid,gid)
 for n,b in values.items():
  p=target(root,cron,n);owner=0 if n=='cron/reconcile' else uid
  current=m.private_bytes(p,owner,private=False)
  m.need(m.digest(current) in (j['entries'][n]['old'],j['entries'][n]['new']),'Concurrent edit preserved: '+n)
  if current!=b:write(p,b,owner,0 if n=='cron/reconcile' else gid)
  if n=='cron/reconcile':os.chmod(p,0o644)
 m.need(all(m.private_bytes(target(root,cron,n),0 if n=='cron/reconcile' else uid,private=False)==b for n,b in values.items()),'Final hashes differ; rerun same repair.')
 j['state']='installed';m.atomic_write(path,m.encode(j),uid,gid)
 return root/'deployment-backups'/j['backup']

def diagnostic(report_source,root):
 module=types.ModuleType('read_only_report');exec(compile(report_source,'read-only-report','exec'),module.__dict__)
 module.report(root,'3EB7F85259')
 module.report(root,'B0AC5BEFEB')
 module.report(root,'E6E183EF8E')
 for service in ('crond','cron'):
  try:
   p=subprocess.run(['systemctl','is-active',service],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=10)
   if p.returncode==0:print('Cron service: active ('+service+')');return
  except (OSError,subprocess.TimeoutExpired):pass
 print('Cron service: not established as active. No service settings changed.')

def main():
 if os.geteuid()!=0:raise RuntimeError('Run in WHM Terminal as root.')
 if sys.argv[1:] not in ([],['--report']):raise RuntimeError('Use no arguments or --report.')
 os.umask(0o077);x,m,old,before,patch,report=load();account=pwd.getpwnam('sitesee');uid,gid=account.pw_uid,account.pw_gid
 if sys.argv[1:]==['--report']:diagnostic(report,ROOT);return
 locks=[]
 try:
  # Root installer lock, worker lock, and the application's existing calendar lock.
  for p in (ROOT,ROOT/'lifecycle-worker.lock',ROOT/'booking-confirmation.lock'):
   if p==ROOT/'lifecycle-worker.lock' and not p.exists():
    created=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600);os.fchown(created,uid,gid);os.close(created)
   if p!=ROOT:m.private_bytes(p,uid,private=False)
   fd=os.open(p,(os.O_RDONLY|os.O_DIRECTORY if p==ROOT else os.O_RDWR)|os.O_NOFOLLOW);locks.append(fd);fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
  php=cli_php(['/opt/cpanel/ea-php82/root/usr/bin/php-cli',m.PHP])
  values=plan(x,m,ROOT,PUBLIC,CRON,uid,old,before,patch,php)
  with tempfile.TemporaryDirectory(prefix='sitesee-repair-lint-') as folder:
   for n,b in patch.items():
    p=Path(folder)/Path(n).name;p.write_bytes(b)
    r=subprocess.run([php,'-l',str(p)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=15)
    m.need(r.returncode==0,'Packaged syntax failed: '+n)
  backup=deploy(m,ROOT,CRON,values,uid,gid)
  p=subprocess.run(['runuser','-u','sitesee','--',php,str(ROOT/'server/booking-lifecycle-reconcile.php'),'--diagnose'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30,cwd=account.pw_dir)
  bootstrap=p.returncode==0 and b'CLI, database and worker selection: PASS.' in p.stdout
  print('FINAL RESULTS\nLegacy cancellation reconciliation: INSTALLED IN TEST MODE | '+REVISION)
  print('Verified legacy cancellation accepted by scheduled and original recovery checks')
  print('Release hashes: PASS\nVerified cron PHP CLI: '+php)
  print('Worker bootstrap: '+('PASS from cron home directory (database and selection checked; no provider writes)' if bootstrap else 'CHECK REQUIRED; no provider request attempted'))
  if not bootstrap:
   for line in p.stdout.decode(errors='replace').splitlines():
    if re.fullmatch(r'[0-9T:+-]+ Worker stopped: stage=[a-z]+; type=[A-Za-z]+; code=[A-Za-z0-9_-]+\.',line):print(line)
  print('Backup: '+str(backup))
  print('No booking row, payment, event, invitation, email or credential changed. Existing database schema checked. Stripe remains TEST.')
 finally:
  for fd in reversed(locks):os.close(fd)
 diagnostic(report,ROOT)

if __name__=='__main__':
 try:main()
 except Exception as e:
  print('FINAL RESULTS\nAppointment repair: CHECK REQUIRED')
  print(str(e) if isinstance(e,RuntimeError) or type(e).__name__=='InstallError' else 'A local check could not complete ('+type(e).__name__+').')
  print('Keep backups. If a job was busy, rerun this same repair. Unknown files are preserved; no rollback is performed.')
  sys.exit(1)
